require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{MariaDbWorkforceScheduler};
