$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_scheduler_race_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='schedule_race_';$barrier=sys_get_temp_dir().'/fm2-scheduler-race-'.bin2hex(random_bytes(5));mkdir($barrier,0700);$children=[];
try{JobsSchemaMigration::apply($db,$p);$scheduler=new MariaDbWorkforceScheduler($db,$p);assertSameValue('2026-09-09T14',$scheduler->tick('2026-09-09T11:20:00.000000Z')['slot'],'causal fixture latest slot14');$db->begin_transaction();$db->query("SELECT schedule_key FROM `{$p}fm2_scheduler_slots` WHERE schedule_key='workforce-hourly-v1/2026-09-09T14' FOR UPDATE");foreach([1,2]as$i){$arrival="$barrier/arrival-$i";$process=proc_open([PHP_BINARY,dirname(__DIR__).'/Support/jobs_scheduler_worker.php',$name,$p,"scheduler-$i",$arrival,"$barrier/release",str_repeat((string)($i+3),64)],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),array_replace(getenv(),['FMONITOR_TEST_DB_ADMIN_PASSWORD'=>$password]));if(!is_resource($process))throw new TestFailure('SETUP_FAILURE scheduler child');$children[]=[$process,$pipes,$arrival];}$deadline=microtime(true)+5;while((!is_file($children[0][2])||!is_file($children[1][2]))&&microtime(true)<$deadline)usleep(1000);assertSameValue(true,is_file($children[0][2])&&is_file($children[1][2]),'both connected children reach pre-tick barrier');file_put_contents("$barrier/release","go\n",LOCK_EX);usleep(100000);foreach($children as[$process])assertSameValue(true,proc_get_status($process)['running'],'both ticks blocked on held latest-slot row');$db->commit();$buffers=array_fill(0,2,['out'=>'','err'=>'','exit'=>null]);foreach($children as[, $pipes])foreach([1,2]as$fd)stream_set_blocking($pipes[$fd],false);$deadline=microtime(true)+10;do{$running=false;foreach($children as$i=>[$process,$pipes]){$buffers[$i]['out'].=stream_get_contents($pipes[1]);$buffers[$i]['err'].=stream_get_contents($pipes[2]);$status=proc_get_status($process);if($status['running'])$running=true;elseif($buffers[$i]['exit']===null)$buffers[$i]['exit']=$status['exitcode'];}if(!$running)break;if(microtime(true)>=$deadline){foreach($children as[$process])if(proc_get_status($process)['running'])proc_terminate($process,9);throw new TestFailure('SETUP_FAILURE scheduler total timeout');}usleep(10000);}while(true);$results=[];foreach($children as$i=>[$process,$pipes]){$buffers[$i]['out'].=stream_get_contents($pipes[1]);$buffers[$i]['err'].=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$closed=proc_close($process);assertSameValue([0,''],[$buffers[$i]['exit']??$closed,$buffers[$i]['err']],'bounded scheduler child');$results[]=json_decode(trim($buffers[$i]['out']),true,512,JSON_THROW_ON_ERROR);}$ids=array_unique(array_column($results,'jobId'));$created=array_column($results,'created');sort($created);assertSameValue([1,[false,true]],[count($ids),$created],'causal concurrent ticks return one job and creator');$job=$db->query("SELECT idempotency_key,payload_json FROM `{$p}fm2_jobs` WHERE idempotency_key='d7f57de3-20d1-441b-94f6-f2ddc79625a2'")->fetch_assoc();assertSameValue(['d7f57de3-20d1-441b-94f6-f2ddc79625a2',['dueAtUtc'=>'2026-09-09T12:07:00.000000Z','runIdentity'=>'d7f57de3-20d1-441b-94f6-f2ddc79625a2','scheduleSlot'=>'2026-09-09T15']],[$job['idempotency_key'],json_decode($job['payload_json'],true,512,JSON_THROW_ON_ERROR)],'causal race exact identity/payload');assertSameValue(1,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_scheduler_slots` WHERE schedule_key='workforce-hourly-v1/2026-09-09T15'")->fetch_assoc()['n'],'one slot persisted');echo"PASS: DURABLE-BACKGROUND-JOBS-001 causal scheduler race\n";
}finally{foreach($children as[$process])if(is_resource($process)){proc_terminate($process,9);proc_close($process);}foreach(glob("$barrier/*")?:[]as$file)unlink($file);rmdir($barrier);$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
